// dsh-hosted-image — a DSH tool that generates one image through a sub2api
// "hosted image" Responses endpoint (SUB2API_HOSTED_IMAGE_TOOLS_ENABLED).
//
// Why a tool instead of an LLM adapter: DSH's pi-ai transport cannot declare a
// `tools:[{type:"image_generation"}]` item, cannot attach a per-call
// Idempotency-Key, and drops `image_generation_call` output items. A tool owns its
// own HTTP, so all three gaps disappear without touching app.asar.
//
// The generated bytes land in the attachment store and come back as an `image`
// block inside the tool result — the one shape that both the Chat UI
// (`tool.call.images`) and pi-ai's `convertToolResultOutput` accept.

import { defineTool } from '@deepseek-ai/dsh-tools';
import { createToolDefinition, readConfig } from './tool.js';

export const name = 'dsh-hosted-image';
export const inject = ['tools'];

/**
 * Retry registration until the tool plane is ready: on 0.2.x cold starts
 * `ctx.tools.register` can succeed silently without the tool reaching the agent.
 */
function registerWhenReady(ctx, register, { retryBaseMs = 1000, retryMax = 5 } = {}) {
  const report = (error) => {
    const message = `dsh-hosted-image: failed to register generate_image: ${String(error?.message ?? error)}`;
    console.error(message);
    ctx.logger?.error?.(message);
  };
  const safeRegister = (attempt) => {
    try {
      register();
    } catch (error) {
      if (/duplicate/i.test(String(error?.message ?? error))) return;
      if (attempt >= retryMax) {
        report(error);
        return;
      }
      const timer = setTimeout(() => safeRegister(attempt + 1), retryBaseMs * 2 ** attempt);
      timer.unref?.();
      ctx.effect?.(() => () => clearTimeout(timer));
    }
  };
  if (typeof ctx.inject === 'function') {
    ctx.inject(['tools'], () => safeRegister(0));
    return;
  }
  safeRegister(0);
}

export function apply(ctx, config) {
  const cfg = readConfig(config);
  if (cfg.baseURL === '' || cfg.model === '') {
    const message =
      'dsh-hosted-image: disabled — set baseURL (the hosted image endpoint, e.g. http://127.0.0.1:8080/v1) ' +
      "and model (the main model name) in this plugin's cordis.patch.yml config, then restart dsh.";
    console.error(message);
    ctx.logger?.warn?.(message);
    return;
  }
  registerWhenReady(ctx, () => {
    ctx.tools.register(createToolDefinition(defineTool, ctx, cfg));
  });
}
